from collections import Counter
from typing import List

class Solution:
    def canPartition(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        if n % k != 0:
            return False

        num_groups = n // k
        counts = Counter(nums)

        # In any group of size k, all elements must be distinct
        # Thus, no element can appear more times than the number of groups
        for val, freq in counts.items():
            if freq > num_groups:
                return False

        return True

#include <vector>
#include <unordered_map>

class Solution {
public:
    bool canPartition(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (n % k != 0) return false;

        int num_groups = n / k;
        std::unordered_map<int, int> counts;
        for (int x : nums) {
            counts[x]++;
            if (counts[x] > num_groups) return false;
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean canPartition(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return false;

        int numGroups = n / k;
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) {
            int freq = counts.getOrDefault(x, 0) + 1;
            if (freq > numGroups) return false;
            counts.put(x, freq);
        }
        return true;
    }
}

var canPartition = function(nums, k) {
    const n = nums.length;
    if (n % k !== 0) return false;

    const numGroups = Math.floor(n / k);
    const counts = new Map();
    for (const x of nums) {
        const freq = (counts.get(x) || 0) + 1;
        if (freq > numGroups) return false;
        counts.set(x, freq);
    }
    return true;
};
